  <?php if (Auth::can('rm.usage')): ?><a class="btn btn-primary btn-sm" href="<?= e(url('inventory/raw-usage')) ?>"><?= __('+ Daily Raw Material Usage') ?></a><?php endif; ?>
  <a class="btn btn-outline btn-sm" href="<?= e(url('inventory/raw-usage/report')) ?>"><?= __('Consumption Report') ?></a>
  <button class="btn btn-dark btn-sm" type="button" onclick="window.print()">🖨 <?= __('Print') ?></button>
</div>
<div class="cards">
  <div class="card accent"><div class="lbl"><?= __('Total Raw Material Qty') ?></div><div class="val"><?= number_format($totQty, 0) ?><span class="muted" style="font-size:14px"> KG</span></div><div class="sub"><?= number_format(UnitConverter::fromKg($totQty, 'TON'), 3) ?> TON · <?= number_format(UnitConverter::fromKg($totQty, 'MAN'), 3) ?> MAN</div></div>
  <?php if ($canMoney): ?><div class="card gold"><div class="lbl"><?= __('Raw Material Stock Value') ?></div><div class="val"><?= money($totValue) ?></div></div><?php endif; ?>
  <div class="card blue"><div class="lbl"><?= __('Used in Production') ?></div><div class="val"><?= number_format($totUsed, 0) ?><span class="muted" style="font-size:14px"> KG</span></div></div>
