</div>
<div class="panel"><h2><?= __('Raw Material Stock — kind: raw & packaging only') ?><span class="muted" style="font-size:12px"><?= __('(separate from Finished Goods — never mixed)') ?></span></h2>
<div class="table-wrap"><table class="tbl"><thead><tr><th><?= __('SKU') ?></th><th><?= __('Product') ?></th><th><?= __('Kind') ?></th><th class="num"><?= __('Purchased') ?></th><th class="num"><?= __('On Hand') ?></th><th class="num"><?= __('Used in Prod') ?></th><th class="num"><?= __('Used Today') ?></th><?php if ($canMoney): ?><th class="num"><?= __('Value') ?></th><?php endif; ?><th class="num"><?= __('Reorder') ?></th><th><?= __('Status') ?></th></tr></thead>
<tbody><?php foreach ($rows as $r): $lowRow = (float)$r['reorder_level'] > 0 && $r['qty'] <= (float)$r['reorder_level']; ?>
<tr style="<?= $lowRow ? 'background:#fdf3ef' : '' ?>"><td class="mono"><?= e($r['sku']) ?></td><td><?= e($r['name']) ?></td><td><span class="badge gray"><?= e(strtoupper($r['kind'])) ?></span></td><td class="num"><?= number_format($r['purchased'], 3) ?> KG</td><td class="num"><strong><?= number_format($r['qty'], 3) ?></strong> KG<div class="muted" style="font-size:11px"><?= number_format(UnitConverter::fromKg($r['qty'], 'TON'), 3) ?> TON · <?= number_format(UnitConverter::fromKg($r['qty'], 'MAN'), 3) ?> MAN</div></td><td class="num"><?= number_format($r['used'], 3) ?> KG</td><td class="num"><?= number_format($r['used_today'], 3) ?> KG</td><?php if ($canMoney): ?><td class="num"><?= money($r['value']) ?></td><?php endif; ?><td class="num"><?= qty($r['reorder_level']) ?><?php if ($lowRow): ?><div class="muted" style="font-size:11px"><?= __('suggested order') ?> ≈ <?= qty(max(0, (float)$r['reorder_level'] * 2 - (float)$r['qty'])) ?></div><?php endif; ?></td><td><?= $lowRow ? '<span class="badge red">LOW</span>' : '<span class="badge green">OK</span>' ?></td></tr>
<?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="<?= $canMoney ? 10 : 9 ?>" class="muted"><?= __('No raw/packaging products on file. Create products with kind “Raw” or “Packaging”.') ?></td></tr><?php endif; ?></tbody></table></div></div>
